const resp = pm.response.json();
const tokenid = resp.token;
pm.variables.set("token_ID",tokenid);

const resp = pm.response.json();
const bookingID = resp.bookingid;
console.log("Booking ID: "+bookingID);
pm.variables.set("bID",bookingID);

const firstname = pm.variables.replaceIn("{{$randomFirstName}}");
const lastname = pm.variables.replaceIn("{{$randomLastName}}");
pm.sendRequest({
    method:'POST',
    url: pm.environment.get('baseURL')+'/booking',
    header:{
        'Content-Type':'application/json'
    },
    body:{
        mode:'raw',
        //javascript to JSON Object
        raw: JSON.stringify({
             "firstname" : firstname,
             "lastname" : lastname,
             "totalprice" : 111,
             "depositpaid" : true,
           "bookingdates" : {
        "checkin" : "2018-01-01",
        "checkout" : "2019-01-01"
    },
    "additionalneeds" : "`Lunch`"

        })
    }
},function(error, response) {
    if(error){
        console.log(error);
    }
    else{
        //JSON Object to javascript Object
        const resp_body = JSON.parse(response.text());
        const booking_id = resp_body.bookingid;
        console.log("booking id: "+booking_id)
        pm.variables.set("bID",booking_id);
    }
} )

